"""
Ops & SRE Agent - Responsible for executing operational and diagnostic terminal commands.
"""

from typing import Any
from ..tools.system_tool import run_system_diagnostic


class OpsDiagnosticsAgent:
    def __init__(self, agent_id: str = "ops-diagnostics-agent") -> None:
        self.agent_id = agent_id

    def execute_terminal_task(self, command: str, client_mode: str = "guarded") -> dict[str, Any]:
        """Executes a diagnostic terminal command generated by the SRE reasoning loop."""
        return run_system_diagnostic(
            command=command,
            client_mode=client_mode,
            agent_id=self.agent_id,
        )

